import json
import re

with open('/app/resources/treasury_bulletin_1969_10.json', 'r') as f:
    data = json.load(f)

# Let's see how many pages/elements there are
def count_elements(element, count=0):
    if isinstance(element, dict):
        count += 1
        for v in element.values():
            count = count_elements(v, count)
    elif isinstance(element, list):
        for item in element:
            count = count_elements(item, count)
    return count

# Get a list of all text content that contains numbers and "January"
def find_january_data(element, path=""):
    results = []
    if isinstance(element, dict):
        if 'content' in element and isinstance(element['content'], str):
            if 'January' in element['content'] and re.search(r'[0-9]{4}', element['content']):
                # Extract all year-January patterns
                matches = re.findall(r'([0-9]{4}\s*-\s*January|[0-9]{4}-January|January\s+[0-9]{4})', element['content'])
                for m in matches:
                    results.append((path, m))
        for k, v in element.items():
            results.extend(find_january_data(v, f"{path}.{k}"))
    elif isinstance(element, list):
        for i, item in enumerate(element):
            results.extend(find_january_data(item, f"{path}[{i}]"))
    return results

results = find_january_data(data)
print(f"Found {len(results)} elements with January data")

# Group by year
year_counts = {}
for path, match in results:
    year = re.search(r'([0-9]{4})', match)
    if year:
        y = year.group(1)
        if y not in year_counts:
            year_counts[y] = []
        year_counts[y].append(match)

for year in sorted(year_counts.keys()):
    print(f"{year}: {year_counts[year]}")
