import re
import json

# Let's find ALL tables that contain debt data and extract year-month rows
with open('/app/resources/treasury_bulletin_1969_10.json', 'r') as f:
    data = json.load(f)

# Get all tables from the document
def get_all_tables(element):
    tables = []
    if isinstance(element, dict):
        if 'content' in element and isinstance(element['content'], str):
            if '<table' in element['content']:
                tables.append(element['content'])
        for v in element.values():
            tables.extend(get_all_tables(v))
    elif isinstance(element, list):
        for item in element:
            tables.extend(get_all_tables(item))
    return tables

tables = get_all_tables(data)
print(f"Found {len(tables)} tables")

# Now search each table for debt data with year-month patterns
debt_data = {}
for i, table in enumerate(tables):
    # Look for tables containing "Total outstanding" which is the gross debt
    if 'Total outstanding' in table and 'Public debt securities' in table:
        # This is the FD-1 table
        # Extract all year-month rows
        rows = re.findall(r'<tr><td>([0-9]{4}-[A-Za-z]+)</td><td>([0-9,]+)</td>', table)
        for year_month, value in rows:
            debt_data[year_month] = value
        print(f"\nTable {i} (FD-1): Found {len(rows)} rows")
        for ym, val in rows:
            print(f"  {ym}: {val}")

# Print all found debt data
print("\n=== All found debt data ===")
for ym in sorted(debt_data.keys()):
    print(f"{ym}: {debt_data[ym]}")
